// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 a, uint256 b, address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok1;
        try c.SetMinSum(a) { ok1 = true; } catch { ok1 = false; }
        vm.prank(caller);
        bool ok2;
        try c.SetMinSum(b) { ok2 = true; } catch { ok2 = false; }

        uint256 finalMin = c.MinSum();

        assertTrue(!ok2 || finalMin == b);
    }
}
